// debugProtobufParse is a test function that mimics the scrape loop's parsing logic
// to help debug protobuf parsing issues with native histogram metrics
func debugProtobufParse(t *testing.T, inputData string) {
	// Convert the hex-escaped string to bytes
	data, err := hexStringToBytes(inputData)
	if err != nil {
		fmt.Printf("ERROR: Failed to convert hex string to bytes: %v\n", err)
		return
	}

	fmt.Printf("=== PROTOBUF DEBUG PARSING ===\n")
	fmt.Printf("Input data length: %d bytes\n", len(data))
	fmt.Printf("Input data (hex): %x\n", data)
	fmt.Printf("Input data (string): %q\n", string(data))

	// Create a symbol table like the scrape loop does
	symbolTable := labels.NewSymbolTable()

	// Create parser with protobuf content type
	contentType := "application/vnd.google.protobuf"
	fallbackType := ""
	parseClassicHistograms := true
	skipOMCTSeries := false

	p, err := textparse.New(data, contentType, fallbackType, parseClassicHistograms, skipOMCTSeries, symbolTable)
	if err != nil {
		fmt.Printf("ERROR: Failed to create parser: %v\n", err)
		return
	}

	fmt.Printf("Parser created successfully\n")

	var (
		total, added int
		lset         labels.Labels
		e            exemplar.Exemplar
		lastMeta     *metaEntry
		lastMFName   []byte
	)

	// Mimic the scrape loop's parsing logic
	for {
		var (
			et              textparse.Entry
			isHistogram     bool
			met             []byte
			parsedTimestamp *int64
			val             float64
			h               *histogram.Histogram
			fh              *histogram.FloatHistogram
		)

		if et, err = p.Next(); err != nil {
			if err.Error() == "EOF" {
				err = nil
			}
			break
		}

		fmt.Printf("\n--- Entry Type: %v ---\n", et)

		switch et {
		case textparse.EntryType:
			lastMFName, lastMeta = setType(p.Type())
			fmt.Printf("TYPE: metric_name=%s, type=%v\n", string(lastMFName), lastMeta.Type)
			continue
		case textparse.EntryHelp:
			lastMFName, lastMeta = setHelp(p.Help())
			fmt.Printf("HELP: metric_name=%s, help=%s\n", string(lastMFName), lastMeta.Help)
			continue
		case textparse.EntryUnit:
			lastMFName, lastMeta = setUnit(p.Unit())
			fmt.Printf("UNIT: metric_name=%s, unit=%s\n", string(lastMFName), lastMeta.Unit)
			continue
		case textparse.EntryComment:
			fmt.Printf("COMMENT: %s\n", string(p.Comment()))
			continue
		case textparse.EntryHistogram:
			isHistogram = true
			fmt.Printf("HISTOGRAM entry detected\n")
		default:
			fmt.Printf("SERIES entry detected\n")
		}
		total++

		// Get the metric data
		if isHistogram {
			met, parsedTimestamp, h, fh = p.Histogram()
			fmt.Printf("HISTOGRAM: metric=%s, timestamp=%v\n", string(met), parsedTimestamp)
			if h != nil {
				fmt.Printf("  Integer Histogram: count=%d, sum=%f, schema=%d\n", h.Count, h.Sum, h.Schema)
				fmt.Printf("  Positive spans: %+v\n", h.PositiveSpans)
				fmt.Printf("  Negative spans: %+v\n", h.NegativeSpans)
			}
			if fh != nil {
				fmt.Printf("  Float Histogram: count=%f, sum=%f, schema=%d\n", fh.Count, fh.Sum, fh.Schema)
				fmt.Printf("  Positive spans: %+v\n", fh.PositiveSpans)
				fmt.Printf("  Negative spans: %+v\n", fh.NegativeSpans)
			}
		} else {
			met, parsedTimestamp, val = p.Series()
			fmt.Printf("SERIES: metric=%s, timestamp=%v, value=%f\n", string(met), parsedTimestamp, val)
		}

		// Get labels
		p.Labels(&lset)
		fmt.Printf("LABELS: %s\n", lset.String())
		fmt.Printf("LABELS detail:\n")
		lset.Range(func(l labels.Label) {
			fmt.Printf("  %s=%s (len=%d)\n", l.Name, l.Value, len(l.Value))
		})

		// Check for bucket metrics specifically (as mentioned in the debug function)
		if strings.Contains(lset.Get(labels.MetricName), "bucket") {
			fmt.Printf("*** BUCKET METRIC DETECTED ***\n")
			fmt.Printf("  Metric name: %s\n", lset.Get(labels.MetricName))
			fmt.Printf("  All labels: %s\n", lset.String())

			// Check for potential issues
			lset.Range(func(l labels.Label) {
				if l.Name == "le" {
					fmt.Printf("  'le' label value: %q (len=%d)\n", l.Value, len(l.Value))
				}
				if l.Name == labels.MetricName {
					fmt.Printf("  Metric name: %q (len=%d)\n", l.Value, len(l.Value))
				}
			})
		}

		// Check exemplars
		exemplars := make([]exemplar.Exemplar, 0, 1)
		for hasExemplar := p.Exemplar(&e); hasExemplar; hasExemplar = p.Exemplar(&e) {
			exemplars = append(exemplars, e)
			fmt.Printf("EXEMPLAR: value=%f, labels=%s\n", e.Value, e.Labels.String())
			e = exemplar.Exemplar{} // Reset for next iteration
		}

		// Check created timestamp
		if ctMs := p.CreatedTimestamp(); ctMs != 0 {
			fmt.Printf("CREATED TIMESTAMP: %d ms\n", ctMs)
		}

		added++
	}

	fmt.Printf("\n=== PARSING SUMMARY ===\n")
	fmt.Printf("Total entries processed: %d\n", total)
	fmt.Printf("Added entries: %d\n", added)
	if err != nil {
		fmt.Printf("Final error: %v\n", err)
	}
}

// Helper functions to mimic the scrape cache behavior
func setType(name []byte, typ model.MetricType) ([]byte, *metaEntry) {
	return name, &metaEntry{
		Metadata: metadata.Metadata{
			Type: typ,
		},
	}
}

func setHelp(name, help []byte) ([]byte, *metaEntry) {
	return name, &metaEntry{
		Metadata: metadata.Metadata{
			Help: string(help),
		},
	}
}

func setUnit(name, unit []byte) ([]byte, *metaEntry) {
	return name, &metaEntry{
		Metadata: metadata.Metadata{
			Unit: string(unit),
		},
	}
}

